from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int], *, max_workers: int | None = None) -> int:
    """Return the sum of square(x) for x in xs, computing squares in a thread pool.

    max_workers is passed to the thread pool; None lets the pool choose.
    The result must be identical for every worker count.
    """
    with ThreadPoolExecutor(max_workers=max_workers) as pool:
        squares = pool.map(square, xs)
        return sum(squares)


@pytest.mark.parametrize("workers", [None, 1, 2, 4, 8])
def test_sum_squares_basic(workers: int | None) -> None:
    assert sum_squares([1, 2, 3], max_workers=workers) == 14


@pytest.mark.parametrize("workers", [None, 1, 2, 4, 8])
def test_sum_squares_empty(workers: int | None) -> None:
    assert sum_squares([], max_workers=workers) == 0


@pytest.mark.parametrize("workers", [None, 1, 2, 4, 8])
def test_sum_squares_negatives(workers: int | None) -> None:
    assert sum_squares([-3, 3, -1], max_workers=workers) == 19


@pytest.mark.parametrize("workers", [None, 1, 2, 4, 8])
def test_sum_squares_large_same_at_every_worker_count(workers: int | None) -> None:
    xs = list(range(-500, 1500))
    expected = sum(square(x) for x in xs)
    assert sum_squares(xs, max_workers=workers) == expected


def test_sum_squares_matches_across_worker_counts() -> None:
    xs = [7, -2, 11, 0, 5, 9, -4]
    results = {sum_squares(xs, max_workers=w) for w in (1, 2, 3, 4, 8)}
    assert len(results) == 1
